-- Demo tenant B: 'Harbour Supplies (Demo)', a generic SME with no Odoo, for testing the
-- MCP tools and the gate question set. All names, numbers and emails are invented
-- (.example domains, +852 5000 01xx numbers). Re-runnable: deletes and recreates the tenant.
-- Run in the SQL Editor; set the owner email at the top.
do $seed$
declare
  v_owner uuid := (select id from auth.users where email = 'kincheonglau@gmail.com');
  v_tenant uuid;
  v_source uuid;
begin
  delete from public.tenants where slug = 'demo-harbour-supplies';
  if v_owner is not null then insert into public.tenant_members (tenant_id, user_id, role) values (v_tenant, v_owner, 'owner'); end if;
  -- Policies are long text, so they are also searchable as knowledge passages.
  select r.tenant_id, r.id, r.title || ': ' || r.body from public.records r where r.tenant_id = v_tenant and r.object_type = 'policy';
end
$seed$;
